-- Hexpath PT (ACME's project tracker) schema.
-- db.py runs this file once, when the database has no "users" table yet.
-- To start over during development, run scripts/reset_db.sql first.

CREATE TYPE "user_role" AS ENUM (
  'admin',
  'manager',
  'employee'
);

CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar UNIQUE NOT NULL,
  "username" varchar UNIQUE NOT NULL,
  "name" varchar NOT NULL,
  "password_hash" varchar NOT NULL,
  "role" user_role NOT NULL DEFAULT 'employee',
  "archived_at" timestamp,
  "created_at" timestamp NOT NULL DEFAULT now()
);

CREATE TABLE "employees" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer UNIQUE NOT NULL,
  "title" varchar,
  "salary" decimal(12,2) NOT NULL DEFAULT 0,
  "manager_id" integer
);

CREATE TABLE "projects" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" varchar NOT NULL,
  "description" text,
  "start_date" date NOT NULL,
  "end_date" date NOT NULL,
  "budget" decimal(14,2) NOT NULL,
  "estimated_hours" decimal(10,2) NOT NULL DEFAULT 0,
  "manager_id" integer NOT NULL,
  "archived_at" timestamp,
  "completed_at" timestamp,
  "created_at" timestamp NOT NULL DEFAULT now()
);

CREATE TABLE "milestones" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "project_id" integer NOT NULL,
  "title" varchar NOT NULL,
  "description" text,
  "start_date" date NOT NULL,
  "end_date" date NOT NULL,
  "completed_at" timestamp,
  "created_at" timestamp NOT NULL DEFAULT now()
);

-- "milestone_id can't start until depends_on_id is complete"
CREATE TABLE "milestone_dependencies" (
  "milestone_id" integer NOT NULL,
  "depends_on_id" integer NOT NULL,
  PRIMARY KEY ("milestone_id", "depends_on_id")
);

CREATE TABLE "milestone_assignments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "milestone_id" integer NOT NULL,
  "employee_id" integer NOT NULL,
  "start_date" date NOT NULL,
  "end_date" date NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT now()
);

CREATE TABLE "time_entries" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "employee_id" integer NOT NULL,
  "milestone_id" integer NOT NULL,
  "work_date" date NOT NULL,
  "hours" decimal(4,2) NOT NULL,
  "hourly_rate" decimal(10,2) NOT NULL,
  "note" text,
  "created_at" timestamp NOT NULL DEFAULT now()
);

CREATE TABLE "budget_history" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "project_id" integer NOT NULL,
  "old_budget" decimal(14,2) NOT NULL,
  "new_budget" decimal(14,2) NOT NULL,
  "reason" text NOT NULL,
  "changed_by" integer NOT NULL,
  "changed_at" timestamp NOT NULL DEFAULT now()
);

CREATE TABLE "audit_log" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "actor_id" integer,
  "actor_role" user_role,
  "action" varchar NOT NULL,
  "entity_type" varchar NOT NULL,
  "entity_id" integer,
  "summary" text,
  "changes" jsonb,
  "created_at" timestamp NOT NULL DEFAULT now()
);

CREATE TABLE "app_settings" (
  "key" varchar PRIMARY KEY,
  "value" text NOT NULL
);

CREATE UNIQUE INDEX ON "time_entries" ("employee_id", "work_date");

ALTER TABLE "employees" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");

ALTER TABLE "employees" ADD FOREIGN KEY ("manager_id") REFERENCES "users" ("id");

ALTER TABLE "projects" ADD FOREIGN KEY ("manager_id") REFERENCES "users" ("id");

ALTER TABLE "milestones" ADD FOREIGN KEY ("project_id") REFERENCES "projects" ("id");

ALTER TABLE "milestone_dependencies" ADD FOREIGN KEY ("milestone_id") REFERENCES "milestones" ("id");

ALTER TABLE "milestone_dependencies" ADD FOREIGN KEY ("depends_on_id") REFERENCES "milestones" ("id");

ALTER TABLE "milestone_assignments" ADD FOREIGN KEY ("milestone_id") REFERENCES "milestones" ("id");

ALTER TABLE "milestone_assignments" ADD FOREIGN KEY ("employee_id") REFERENCES "employees" ("id");

ALTER TABLE "time_entries" ADD FOREIGN KEY ("employee_id") REFERENCES "employees" ("id");

ALTER TABLE "time_entries" ADD FOREIGN KEY ("milestone_id") REFERENCES "milestones" ("id");

ALTER TABLE "budget_history" ADD FOREIGN KEY ("project_id") REFERENCES "projects" ("id");

ALTER TABLE "budget_history" ADD FOREIGN KEY ("changed_by") REFERENCES "users" ("id");

ALTER TABLE "audit_log" ADD FOREIGN KEY ("actor_id") REFERENCES "users" ("id");
